import pyomo.environ as pyo

DATA = {
    "products": ["butter", "sauce", "jelly"],
    "resources": ["cook", "labor", "apples"],
    "revenue": {"butter": 190, "sauce": 170, "jelly": 155},
    "usage": {
        "cook":   {"butter": 3.5, "sauce": 5.2, "jelly": 2.8},
        "labor":  {"butter": 1.2, "sauce": 0.8, "jelly": 1.5},
        "apples": {"butter": 40,  "sauce": 55,  "jelly": 20},
    },
    "availability": {"cook": 500, "labor": 240, "apples": 6500},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    model.x = pyo.Var(model.P, domain=pyo.NonNegativeIntegers)

    def revenue_rule(m):
        return sum(d["revenue"][p] * m.x[p] for p in m.P)

    model.obj = pyo.Objective(expr=revenue_rule, sense=pyo.maximize)

    def resource_rule(m, r):
        return sum(d["usage"][r][p] * m.x[p] for p in m.P) <= d["availability"][r]

    model.resource_limit = pyo.Constraint(model.R, rule=resource_rule)

    return model
